fn is_digit(c: Int) -> Bool {
  return c >= 48 and c <= 57
}

fn skip_spaces(cs: List[Int], pos: Int) -> Int {
  var p = pos
  while p < cs.len() and cs.get_or(p, 0) == 32 {
    p = p + 1
  }
  return p
}

fn parse_number(cs: List[Int], pos: Int) -> Result[Pair[Int, Int], Str] {
  var p = pos
  var num = 0
  while p < cs.len() and is_digit(cs.get_or(p, 0)) {
    num = num * 10 + (cs.get_or(p, 0) - 48)
    p = p + 1
  }
  if p == pos {
    return Err("syntax error")
  }
  return Ok(Pair { first: num, second: p })
}

fn parse_factor(cs: List[Int], pos: Int) -> Result[Pair[Int, Int], Str] {
  let p = skip_spaces(cs, pos)
  if p >= cs.len() {
    return Err("syntax error")
  }
  let c = cs.get_or(p, 0)
  if c == 45 {
    let inner = parse_factor(cs, p + 1)?
    return Ok(Pair { first: 0 - inner.first, second: inner.second })
  }
  if c == 40 {
    let inner = parse_expr(cs, p + 1)?
    let q = skip_spaces(cs, inner.second)
    if q >= cs.len() or cs.get_or(q, 0) != 41 {
      return Err("syntax error")
    }
    return Ok(Pair { first: inner.first, second: q + 1 })
  }
  return parse_number(cs, p)
}

fn parse_term(cs: List[Int], pos: Int) -> Result[Pair[Int, Int], Str] {
  let lhs = parse_factor(cs, pos)?
  var value = lhs.first
  var p = lhs.second
  while true {
    let q = skip_spaces(cs, p)
    if q >= cs.len() {
      break
    }
    let op = cs.get_or(q, 0)
    if op != 42 and op != 47 {
      break
    }
    let rhs = parse_factor(cs, q + 1)?
    if op == 47 {
      let divisor = rhs.first
      if divisor == 0 {
        return Err("division by zero")
      }
      value = value / divisor
    } else {
      value = value * rhs.first
    }
    p = rhs.second
  }
  return Ok(Pair { first: value, second: p })
}

fn parse_expr(cs: List[Int], pos: Int) -> Result[Pair[Int, Int], Str] {
  let lhs = parse_term(cs, pos)?
  var value = lhs.first
  var p = lhs.second
  while true {
    let q = skip_spaces(cs, p)
    if q >= cs.len() {
      break
    }
    let op = cs.get_or(q, 0)
    if op != 43 and op != 45 {
      break
    }
    let rhs = parse_term(cs, q + 1)?
    if op == 43 {
      value = value + rhs.first
    } else {
      value = value - rhs.first
    }
    p = rhs.second
  }
  return Ok(Pair { first: value, second: p })
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let cs = expr.codes()
  let start = skip_spaces(cs, 0)
  let parsed = parse_expr(cs, start)?
  let stop = skip_spaces(cs, parsed.second)
  if stop != cs.len() {
    return Err("syntax error")
  }
  return Ok(parsed.first)
}
